CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.store_analytics_gateway_ingest(p_secret text, p_event_id uuid, p_visitor uuid, p_session uuid, p_event text, p_product bigint, p_page text, p_fingerprint text, p_channel text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_secret is null or length(p_secret)<>64 or not exists(
  select 1 from store_private.analytics_gateway_secret where singleton and secret_hash=sha256(convert_to(p_secret,'UTF8'))
 ) then raise exception 'Unauthorized' using errcode='42501';end if;
 return public.store_analytics_ingest(p_event_id,p_visitor,p_session,p_event,p_product,p_page,p_fingerprint,p_channel);
end; $function$

CREATE OR REPLACE FUNCTION public.store_analytics_ingest(p_event_id uuid, p_visitor uuid, p_session uuid, p_event text, p_product bigint, p_page text, p_fingerprint text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer;k text;new_session boolean;
begin
 if p_event not in ('visit','heartbeat','page_view','product_view','wishlist_add','wishlist_remove','cart_add','cart_remove','checkout_open','manager_open','manager_product','manager_search_product','manager_general','manager_sell','manager_authentication','manager_atelier','channel_julia_main','channel_julia_outlet','channel_vasya_main','channel_vasya_outlet') or p_visitor is null or p_session is null or p_event_id is null or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then return false;end if;
 if p_event is null or (p_page is not null and p_page not in ('catalog','wishlist','cart')) then return false;end if;
 if p_event in ('product_view','wishlist_add','wishlist_remove','cart_add','cart_remove','manager_product','manager_search_product') and p_product is null then return false;end if;
 if p_product is not null and not exists(select 1 from public.products where id=p_product and available=true) then return false;end if;

 begin
 if exists(select 1 from store_private.analytics_events where event_id=p_event_id) then return true;end if;
 foreach k in array array['ip:'||p_fingerprint,'visitor:'||p_visitor::text,'global:minute','global:day:'||current_date::text,'ip:day:'||current_date::text||':'||p_fingerprint] loop
  insert into store_private.analytics_limits as l(key,window_at,hits) values(k,case when k like 'global:day:%' or k like 'ip:day:%' then date_trunc('day',now()) else date_trunc('minute',now()) end,1)
  on conflict(key) do update set window_at=excluded.window_at,hits=case when l.window_at=excluded.window_at then l.hits+1 else 1 end returning hits into n;
  if n>(case when k='global:minute' then 2400 when k like 'global:day:%' then 250000 when k like 'ip:day:%' then 20000 when k like 'ip:%' then 600 else 120 end) then raise exception using errcode='JP429',message='analytics refused';end if;
 end loop;
 new_session:=not exists(select 1 from store_private.analytics_sessions where session_id=p_session);
 if new_session then
  foreach k in array array['sessions:global','sessions:ip:'||p_fingerprint] loop
   insert into store_private.analytics_limits as l(key,window_at,hits) values(k,date_trunc('minute',now()),1)
   on conflict(key) do update set window_at=excluded.window_at,hits=case when l.window_at=excluded.window_at then l.hits+1 else 1 end returning hits into n;
   if n>(case when k='sessions:global' then 300 else 150 end) then raise exception using errcode='JP429',message='analytics refused';end if;
  end loop;
 end if;
 insert into store_private.analytics_sessions as s(session_id,visitor_id) values(p_session,p_visitor) on conflict(session_id) do update set last_seen=now() where s.visitor_id=excluded.visitor_id;
 if not found then raise exception using errcode='JP429',message='analytics refused';end if;
 if p_event<>'heartbeat' then insert into store_private.analytics_events(event_id,visitor_id,session_id,event,product_id,page) values(p_event_id,p_visitor,p_session,p_event,p_product,p_page) on conflict(event_id) do nothing;end if;
 -- Daily cron owns retention; ingestion only records the event.
 return true;
 exception when sqlstate 'JP429' then return false;
 end;
end; $function$

CREATE OR REPLACE FUNCTION public.store_analytics_ingest(p_event_id uuid, p_visitor uuid, p_session uuid, p_event text, p_product bigint, p_page text, p_fingerprint text, p_channel text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer;k text;new_session boolean;
begin
 if p_channel is null or p_channel not in ('website','telegram','legacy') then return false;end if;
 if p_event not in ('visit','heartbeat','page_view','product_view','wishlist_add','wishlist_remove','cart_add','cart_remove','checkout_open','manager_open','manager_product','manager_search_product','manager_general','manager_sell','manager_authentication','manager_atelier','channel_julia_main','channel_julia_outlet','channel_vasya_main','channel_vasya_outlet') or p_visitor is null or p_session is null or p_event_id is null or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then return false;end if;
 if p_event is null or (p_page is not null and p_page not in ('catalog','wishlist','cart')) then return false;end if;
 if p_event in ('product_view','wishlist_add','wishlist_remove','cart_add','cart_remove','manager_product','manager_search_product') and p_product is null then return false;end if;
 if p_product is not null and not exists(select 1 from public.products where id=p_product and available=true) then return false;end if;

 begin
 if exists(select 1 from store_private.analytics_events where event_id=p_event_id) then return exists(select 1 from store_private.analytics_events where event_id=p_event_id and visitor_id=p_visitor and session_id=p_session and channel=p_channel);end if;
 foreach k in array array['ip:'||p_fingerprint,'visitor:'||p_visitor::text,'global:minute','global:day:'||current_date::text,'ip:day:'||current_date::text||':'||p_fingerprint] loop
  insert into store_private.analytics_limits as l(key,window_at,hits) values(k,case when k like 'global:day:%' or k like 'ip:day:%' then date_trunc('day',now()) else date_trunc('minute',now()) end,1)
  on conflict(key) do update set window_at=excluded.window_at,hits=case when l.window_at=excluded.window_at then l.hits+1 else 1 end returning hits into n;
  if n>(case when k='global:minute' then 2400 when k like 'global:day:%' then 250000 when k like 'ip:day:%' then 20000 when k like 'ip:%' then 600 else 120 end) then raise exception using errcode='JP429',message='analytics refused';end if;
 end loop;
 new_session:=not exists(select 1 from store_private.analytics_sessions where session_id=p_session);
 if new_session then
  foreach k in array array['sessions:global','sessions:ip:'||p_fingerprint] loop
   insert into store_private.analytics_limits as l(key,window_at,hits) values(k,date_trunc('minute',now()),1)
   on conflict(key) do update set window_at=excluded.window_at,hits=case when l.window_at=excluded.window_at then l.hits+1 else 1 end returning hits into n;
   if n>(case when k='sessions:global' then 300 else 150 end) then raise exception using errcode='JP429',message='analytics refused';end if;
  end loop;
 end if;
 insert into store_private.analytics_sessions as s(session_id,visitor_id,channel) values(p_session,p_visitor,p_channel) on conflict(session_id) do update set last_seen=now() where s.visitor_id=excluded.visitor_id and s.channel=excluded.channel;
 if not found then raise exception using errcode='JP429',message='analytics refused';end if;
 if p_event<>'heartbeat' then insert into store_private.analytics_events(event_id,visitor_id,session_id,event,product_id,page,channel) values(p_event_id,p_visitor,p_session,p_event,p_product,p_page,p_channel) on conflict(event_id) do nothing;end if;
 -- Daily cron owns retention; ingestion only records the event.
 return true;
 exception when sqlstate 'JP429' then return false;
 end;
end; $function$

CREATE OR REPLACE FUNCTION public.store_product_wishlist_counts(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare days integer=greatest(1,least(30,coalesce(p_days,30)));counts jsonb;
begin
 if not store_private.admin_mfa_satisfied() or not exists(select 1 from public.store_admins where user_id=auth.uid()) then raise exception 'admin required' using errcode='42501';end if;
 select coalesce(jsonb_object_agg(product_id::text,n),'{}'::jsonb) into counts from(select product_id,count(*) n from store_private.analytics_events where event='wishlist_add' and product_id is not null and created_at>=now()-make_interval(days=>days) group by product_id)t;
 return jsonb_build_object('days',days,'counts',counts);
end;$function$

CREATE OR REPLACE FUNCTION store_gateway.admin_bff_session(p_secret text, p_action text, p_id text, p_payload text DEFAULT NULL::text, p_auth_session uuid DEFAULT NULL::uuid, p_user uuid DEFAULT NULL::uuid, p_lease uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '2s'
AS $function$
declare s store_private.admin_bff_sessions%rowtype;deadline timestamptz;
begin
 perform store_private.operational_secret('session',p_secret);
 if p_id is null or p_id !~ '^[a-f0-9]{64}$' then raise exception 'Invalid handle' using errcode='22023';end if;
 if p_action='rate' then return to_jsonb(store_private.operational_rate('login:'||p_id,12) and store_private.operational_rate('login-day:'||p_id,150,'day'));end if;
 if p_action='create' then
  select least(a.created_at+interval '30 days',coalesce(a.not_after,'infinity'::timestamptz)) into deadline
  from auth.sessions a join auth.users u on u.id=a.user_id where a.id=p_auth_session and a.user_id=p_user and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now());
  if deadline is null or deadline<=now() then raise exception 'Session expired' using errcode='PT401';end if;
  insert into store_private.admin_bff_sessions(id,user_id,auth_session_id,payload,expires_at) values(p_id,p_user,p_auth_session,p_payload,deadline) returning * into s;
 elsif p_action='delete' then delete from store_private.admin_bff_sessions where id=p_id;return 'true'::jsonb;
 else
  select b.* into s from store_private.admin_bff_sessions b join auth.sessions a on a.id=b.auth_session_id join auth.users u on u.id=b.user_id
   where b.id=p_id and b.expires_at>now() and a.created_at>now()-interval '30 days' and (a.not_after is null or a.not_after>now()) and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()) for update of b;
  if not found then return null;end if;
  if p_action='lock' then
   if s.lease_until>clock_timestamp() then return jsonb_build_object('busy',true);end if;
   update store_private.admin_bff_sessions set lease=gen_random_uuid(),lease_until=clock_timestamp()+interval '60 seconds' where id=p_id returning * into s;
  elsif p_action='commit' then
   if p_lease is null or s.lease is distinct from p_lease or s.lease_until<=clock_timestamp() then raise exception 'Session changed' using errcode='PT409';end if;
   update store_private.admin_bff_sessions set payload=p_payload,lease=null,lease_until=null where id=p_id returning * into s;
  elsif p_action='unlock' then
   update store_private.admin_bff_sessions set lease=null,lease_until=null where id=p_id and lease=p_lease;return 'true'::jsonb;
  elsif p_action<>'read' then raise exception 'Invalid session action' using errcode='22023';end if;
 end if;
 return jsonb_build_object('payload',s.payload,'lease',s.lease,'expires_at',s.expires_at,'server_now',now(),'user_id',s.user_id,'auth_session_id',s.auth_session_id);
end $function$

CREATE OR REPLACE FUNCTION store_gateway.bot_claim(p_secret text, p_update_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 perform store_private.operational_secret('bot',p_secret);
 update store_private.bot_outbox set state='failed',payload=null,error_code='retry_exhausted',finished_at=now(),lease=null,lease_until=null
 where state in ('pending','retry','sending') and (created_at<now()-interval '24 hours' or attempts>=6) and (lease_until is null or lease_until<=now());
 with due as(select update_id from store_private.bot_outbox where (p_update_id is null or update_id=p_update_id) and available_at<=now()
  and (state in ('pending','retry') or state='sending' and lease_until<=now()) and attempts<6 order by available_at,update_id for update skip locked limit 5),
 claimed as(update store_private.bot_outbox b set state='sending',attempts=attempts+1,lease=gen_random_uuid(),lease_until=now()+interval '120 seconds'
  from due where b.update_id=due.update_id returning b.update_id,b.payload,b.lease,b.attempts)
 select coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) into result from claimed c;
 return result;
end $function$

CREATE OR REPLACE FUNCTION store_gateway.bot_enqueue(p_secret text, p_update_id bigint, p_chat_hash text, p_kind text, p_payload text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result text;
begin
 perform store_private.operational_secret('bot',p_secret);
 if p_payload is null or length(p_payload) not between 40 and 24000 then raise exception 'Invalid payload' using errcode='22023';end if;
 -- The existing limiter serializes admission and update IDs; enqueue is the SAME transaction.
 if store_private.consume_telegram_update(p_chat_hash,p_update_id,p_kind) then
  insert into store_private.bot_outbox(update_id,chat_hash,kind,payload) values(p_update_id,p_chat_hash,p_kind,p_payload) on conflict(update_id) do nothing;
 end if;
 select state into result from store_private.bot_outbox where update_id=p_update_id and chat_hash=p_chat_hash;
 return coalesce(result,'suppressed');
end $function$

CREATE OR REPLACE FUNCTION store_gateway.client_error_ingest(p_secret text, p_ip text, p_surface text, p_kind text, p_asset text, p_line integer, p_column integer, p_release text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare error_fingerprint text;
begin
 perform store_private.operational_secret('errors',p_secret);
 if p_ip is null or p_ip !~ '^[a-f0-9]{64}$' or p_surface is null or p_surface not in ('website','telegram','admin') or p_kind is null or p_kind not in ('TypeError','ReferenceError','SyntaxError','RangeError','Error','PromiseRejection','ResourceError')
 or p_asset is null or p_asset !~ '^[a-zA-Z0-9_-]{1,80}\.(js|css)$' or p_line is null or p_line not between 0 and 1000000 or p_column is null or p_column not between 0 and 1000000 or p_release is null or p_release !~ '^[a-f0-9]{7,40}$|^development$' then return false;end if;
 if not store_private.operational_rate('errors:ip:'||p_ip,20) or not store_private.operational_rate('errors:global',500) or not store_private.operational_rate('errors:day',10000,'day') then return false;end if;
 error_fingerprint:=encode(sha256(convert_to(concat_ws(':',p_surface,p_kind,p_asset,p_line,p_column,p_release),'UTF8')),'hex');
 insert into store_private.client_errors(fingerprint,surface,kind,asset,line_no,column_no,release) values(error_fingerprint,p_surface,p_kind,p_asset,p_line,p_column,p_release)
 on conflict(fingerprint,bucket_at) do update set hits=client_errors.hits+1,last_seen=now();
 return true;
end $function$

CREATE OR REPLACE FUNCTION store_private.add_workspace_admin(p_email text, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target uuid;
begin
 perform store_private.require_workspace_admin(true);
 if p_email is null or char_length(p_email)>320 or p_name is null or char_length(btrim(p_name)) not between 1 and 100 then raise exception 'Укажите email и имя администратора';end if;
 select u.id into target from auth.users u where lower(u.email)=lower(btrim(p_email)) and u.email_confirmed_at is not null and u.deleted_at is null and (u.banned_until is null or u.banned_until<now())
 and exists(select 1 from auth.mfa_factors f where f.user_id=u.id and f.status='verified' and f.factor_type='totp');
 if target is null then raise exception 'Сотрудник должен подтвердить почту и настроить MFA до предоставления доступа';end if;
 if exists(select 1 from public.store_admins where user_id=target) then raise exception 'У этого аккаунта уже есть доступ';end if;
 insert into public.store_admins(user_id,display_name,access_role) values(target,btrim(p_name),'admin');
 delete from store_private.admin_invitations where lower(email)=lower(btrim(p_email));
 return store_private.workspace_team();
end; $function$

CREATE OR REPLACE FUNCTION store_private.begin_workspace_invite(p_email text, p_name text, p_operation uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform store_private.require_workspace_admin(true);
 if p_operation is null or p_email is null or char_length(p_email)>320 or btrim(p_email)!~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or p_name is null or char_length(btrim(p_name)) not between 1 and 100 then raise exception 'Укажите корректные email и имя';end if;
 perform pg_advisory_xact_lock(840120261012::bigint);
 if exists(select 1 from auth.users where lower(email)=lower(btrim(p_email))) then raise exception 'Аккаунт уже создан. Используйте восстановление пароля и отдельное подтверждение доступа.';end if;
 if exists(select 1 from store_private.admin_invitations where email=lower(btrim(p_email)) and delivery_status='pending' and created_at>now()-interval '2 minutes') then raise exception 'Предыдущее приглашение ещё отправляется. Обновите список через две минуты.';end if;
 if (select count(*) from store_private.workspace_invite_attempts where attempted_at>now()-interval '1 hour' and delivery_status in ('sent','pending','unknown'))>=10 then raise exception 'Лимит отправки: 10 приглашений в час. Попробуйте позже.';end if;
 if (select count(*) from store_private.workspace_invite_attempts where attempted_at>now()-interval '1 hour')>=30 then raise exception 'Слишком много попыток отправки. Попробуйте через час.';end if;
 insert into store_private.workspace_invite_attempts(actor_id,operation_id,delivery_status) values(auth.uid(),p_operation,'pending');
 insert into store_private.admin_invitations(email,display_name,invited_by,created_at,expires_at,delivery_operation,delivery_status,delivery_error)
 values(lower(btrim(p_email)),btrim(p_name),auth.uid(),now(),now()+interval '7 days',p_operation,'pending',null)
 on conflict(email) do update set display_name=excluded.display_name,invited_by=excluded.invited_by,created_at=excluded.created_at,expires_at=excluded.expires_at,delivery_operation=excluded.delivery_operation,delivery_status='pending',delivery_error=null;
 return true;
end $function$

CREATE OR REPLACE FUNCTION store_private.consume_telegram_update(p_chat_hash text, p_update_id bigint, p_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '2s'
AS $function$
DECLARE
  t timestamptz; m timestamptz; d timestamptz;
  g store_private.telegram_limit_global%ROWTYPE;
  c integer; cap integer; daily_count integer;
BEGIN
  IF p_chat_hash IS NULL OR p_chat_hash !~ '^[a-f0-9]{64}$' OR p_update_id IS NULL
    OR p_update_id < 0 OR p_update_id > 9007199254740991
    OR p_kind IS NULL OR p_kind NOT IN ('message','callback') THEN
    RAISE EXCEPTION 'Invalid limiter input' USING ERRCODE='22023';
  END IF;
  -- One row serializes all replicas and prevents overshoot under concurrent requests.
  SELECT * INTO STRICT g FROM store_private.telegram_limit_global WHERE id=true FOR UPDATE;
  t := clock_timestamp();
  m := date_trunc('minute',t); d := date_trunc('day',t AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
  DELETE FROM store_private.telegram_limit_updates WHERE expires_at <= t;
  DELETE FROM store_private.telegram_limit_chats WHERE window_start < m;
  IF EXISTS(SELECT 1 FROM store_private.telegram_limit_updates WHERE update_id=p_update_id) THEN RETURN false; END IF;
  IF g.minute_start <> m THEN g.minute_start:=m; g.minute_count:=0; END IF;
  IF g.day_start <> d THEN g.day_start:=d; g.day_count:=0; END IF;
  IF g.minute_count >= 600 OR g.day_count >= 20000 THEN RETURN false; END IF;
  SELECT count INTO c FROM store_private.telegram_limit_chats WHERE chat_hash=p_chat_hash AND kind=p_kind;
  cap := CASE WHEN p_kind='message' THEN 5 ELSE 30 END;
  IF coalesce(c,0) >= cap THEN RETURN false; END IF;
  SELECT count INTO daily_count FROM store_private.telegram_limit_chat_days WHERE chat_hash=p_chat_hash AND kind=p_kind AND day_start=d;
  IF coalesce(daily_count,0) >= (CASE WHEN p_kind='message' THEN 100 ELSE 500 END) THEN RETURN false; END IF;
  INSERT INTO store_private.telegram_limit_chat_days AS c VALUES(p_chat_hash,p_kind,d,1)
    ON CONFLICT(chat_hash,kind) DO UPDATE SET day_start=excluded.day_start,
      count=CASE WHEN c.day_start=excluded.day_start THEN c.count+1 ELSE 1 END;
  DELETE FROM store_private.telegram_limit_chat_days WHERE day_start<d;
  INSERT INTO store_private.telegram_limit_updates VALUES(p_update_id,t+interval '24 hours');
  INSERT INTO store_private.telegram_limit_chats VALUES(p_chat_hash,p_kind,m,1)
    ON CONFLICT(chat_hash,kind) DO UPDATE SET count=telegram_limit_chats.count+1;
  UPDATE store_private.telegram_limit_global SET minute_start=m, minute_count=g.minute_count+1,
    day_start=d, day_count=g.day_count+1 WHERE id=true;
  RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION store_private.enforce_own_admin_mfa()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not store_private.admin_session_active() or (auth.jwt()->>'aal') is distinct from 'aal2'
 or not exists(select 1 from public.store_admins where user_id=auth.uid())
 or not exists(select 1 from auth.mfa_factors where user_id=auth.uid() and status='verified') then
  raise exception 'Verified administrator MFA required' using errcode='42501';
 end if;
 insert into store_private.admin_mfa_enforcement(user_id) values(auth.uid()) on conflict do nothing;
 delete from store_private.admin_mfa_pauses where user_id=auth.uid();
 return true;
end;
$function$

CREATE OR REPLACE FUNCTION store_private.finance_history(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 perform store_private.require_workspace_admin(true);
 select coalesce(jsonb_agg(to_jsonb(c) order by id::bigint desc),'[]'::jsonb) into result from (
  select id::text,changed_at,actor_label,before_data,after_data from store_private.finance_changes c0 where entity='finance_entries' and record_id=p_id::text order by c0.id desc limit 20
 ) c;return result;
end $function$

CREATE OR REPLACE FUNCTION store_private.finish_workspace_invite(p_operation uuid, p_status text, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_status not in ('sent','failed','unknown') or p_status is null then raise exception 'Invalid delivery status';end if;
 update store_private.workspace_invite_attempts set delivery_status=p_status where operation_id=p_operation and delivery_status='pending';
 if not found then return false;end if;
 update store_private.admin_invitations set delivery_status=p_status,delivery_error=left(p_error,100) where delivery_operation=p_operation;
 return true;
end $function$

CREATE OR REPLACE FUNCTION store_private.guard_product_archive()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.available then new.archive_status:=null;
 elsif new.archive_status is null then new.archive_status:='legacy'; end if;
 if tg_op='UPDATE' and old.archive_status='sold' and new.archive_status is distinct from 'sold'
 and exists(select 1 from store_private.product_sales where product_id=old.id and voided_at is null and after_state->>'archive_status'='sold') then
  raise exception 'Для возврата проданной вещи отмените продажу в истории продаж';
 end if;
 if new.archive_status='sold' and not exists(select 1 from store_private.product_sales where product_id=new.id and voided_at is null and after_state->>'archive_status'='sold') then
  raise exception 'Отметьте продажу через форму с датой и суммой';
 end if;
 if not new.available then new.reserved:=false; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION store_private.link_finance_order(p_order uuid, p_sale uuid, p_order_revision bigint, p_sale_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o store_private.finance_entries%rowtype;s store_private.finance_entries%rowtype; sid bigint;k text;
begin
 perform store_private.require_workspace_admin(true);
 if p_order is null or p_sale is null or p_order=p_sale then raise exception 'Выберите заказ и продажу'; end if;
 select sale_id into sid from store_private.finance_entries where id=p_sale;
 if sid is null then raise exception 'Продажа не найдена'; end if;
 perform 1 from store_private.product_sales where id=sid for update;
 perform 1 from store_private.finance_entries where id in (p_order,p_sale) order by id for update;
 select * into o from store_private.finance_entries where id=p_order;select * into s from store_private.finance_entries where id=p_sale;
 if o.id is null or o.sale_id is not null or o.status in ('linked','cancelled') or s.sale_id is null or s.status<>'completed'
  or exists(select 1 from store_private.finance_entries where merged_into=s.id) then raise exception 'Этот заказ или продажу уже нельзя связать'; end if;
 if p_order_revision is distinct from o.revision or p_sale_revision is distinct from s.revision then raise exception 'Запись изменилась. Обновите отчёт.' using errcode='40001'; end if;
 if o.amount<>s.amount or o.quantity<>s.quantity or o.on_commission<>s.on_commission or o.opened_on>s.completed_on
  or (o.product_id is not null and o.product_id is distinct from s.product_id) then raise exception 'Сверьте сумму, количество, комиссию, дату заказа и артикул с выбранной продажей'; end if;
 foreach k in array array['received','purchase_cost','expenses','owner_due','owner_paid'] loop
  if (to_jsonb(o)->>k) is not null and (to_jsonb(s)->>k) is not null and to_jsonb(o)->k<>to_jsonb(s)->k then raise exception 'В заказе и продаже разные финансовые данные (%). Сначала сверьте суммы.',k; end if;
 end loop;
 update store_private.finance_entries set kind='order',on_order=true,opened_on=o.opened_on,
  received=coalesce(o.received,s.received),purchase_cost=coalesce(o.purchase_cost,s.purchase_cost),expenses=coalesce(o.expenses,s.expenses),
  owner_due=coalesce(o.owner_due,s.owner_due),owner_paid=coalesce(o.owner_paid,s.owner_paid),owner_ref=coalesce(nullif(o.owner_ref,''),s.owner_ref),
  client_ref=coalesce(nullif(o.client_ref,''),s.client_ref),note=left(concat_ws(E'\n',nullif(s.note,''),nullif(o.note,'')),2000),
  revision=revision+1,updated_at=now(),updated_by=auth.uid() where id=p_sale;
 update store_private.finance_entries set status='linked',merged_into=p_sale,revision=revision+1,updated_at=now(),updated_by=auth.uid() where id=p_order;
 return jsonb_build_object('saved',true,'id',p_sale);
end $function$

CREATE OR REPLACE FUNCTION store_private.log_store_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); before_data jsonb; after_data jsonb; label text;
begin
 if tg_table_schema<>'public' or tg_table_name not in ('products','store_admins','product_admin_notes') or tg_when<>'AFTER' then raise exception 'Unexpected audit trigger target'; end if;
 if actor is null and current_setting('role',true)='authenticated' then raise exception 'Authenticated actor is required' using errcode='42501'; end if;
 if tg_op<>'INSERT' then before_data:=to_jsonb(old); end if;
 if tg_op<>'DELETE' then after_data:=to_jsonb(new); end if;
 if tg_op='UPDATE' and (before_data-'revision')=(after_data-'revision') then return new; end if;
 if actor is not null then
  select coalesce(nullif(a.display_name,''),u.email,actor::text) into label from auth.users u left join public.store_admins a on a.user_id=u.id where u.id=actor;
 end if;
 insert into store_private.store_change_log(actor_id,actor_label,actor_role,entity,operation,record_id,before_row,after_row)
 values(actor,coalesce(label,case when actor is null then 'Системное изменение' else actor::text end),coalesce(auth.jwt()->>'role',session_user::text),tg_table_name,tg_op,
 coalesce(after_data->>'id',before_data->>'id',after_data->>'user_id',before_data->>'user_id',after_data->>'product_id',before_data->>'product_id'),before_data,after_data);
 if tg_op='DELETE' then return old; end if; return new;
end $function$

CREATE OR REPLACE FUNCTION store_private.normalize_stock(value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare result jsonb:='{}'::jsonb; item record; k text;
begin
 if value is null then return null; end if;
 if jsonb_typeof(value)<>'object' then raise exception 'Остатки должны быть объектом'; end if;
 for item in select * from jsonb_each(value) loop
  k:=store_private.normalize_variant(item.key);
  if result ? k then raise exception 'Размер % указан несколько раз. Проверьте фактический остаток',k; end if;
  result:=result||jsonb_build_object(k,item.value);
 end loop;
 return result;
end $function$

CREATE OR REPLACE FUNCTION store_private.normalize_variant(value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s text:=btrim(value); latin text;
begin
 s:=regexp_replace(s,'^([0-9]+),([0-9]+)$','\1.\2');
 if s ~* '^(one[ -]?size|o[ /-]?s|единый размер|универсальный)$' then return 'One Size'; end if;
 latin:=upper(translate(s,'ХхМмСс','XXMMSS'));
 latin:=case latin when '2XL' then 'XXL' when '3XL' then 'XXXL' when 'XXXXL' then '4XL' else latin end;
 if latin ~ '^([2-6]?X{1,4}[SL]|[SML])$' then return latin; end if;
 return regexp_replace(s,'^Длинна:','Длина:','i');
end $function$

CREATE OR REPLACE FUNCTION store_private.operational_retention()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 delete from store_private.admin_bff_sessions where expires_at<=now();
 delete from store_private.operational_limits where window_at<now()-interval '2 days';
 update store_private.bot_outbox set state='failed',payload=null,finished_at=now(),error_code='expired',lease=null,lease_until=null where state in ('pending','retry','sending') and created_at<now()-interval '24 hours';
 delete from store_private.bot_outbox where created_at<now()-interval '7 days';
 delete from store_private.client_errors where bucket_at<now()-interval '30 days';
end $function$

CREATE OR REPLACE FUNCTION store_private.operational_secret(p_kind text, p_secret text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare valid boolean:=false;
begin
 if p_secret is not null and length(p_secret)=64 then
  if p_kind='session' then select exists(select 1 from store_private.admin_bff_secret where singleton and secret_hash=sha256(convert_to(p_secret,'UTF8'))) into valid;
  elsif p_kind='bot' then select exists(select 1 from store_private.telegram_limit_secret where id and secret_hash=sha256(convert_to(p_secret,'UTF8'))) into valid;
  elsif p_kind='errors' then select exists(select 1 from store_private.analytics_gateway_secret where singleton and secret_hash=sha256(convert_to(p_secret,'UTF8'))) into valid;
  end if;
 end if;
 if not valid then raise exception 'Unauthorized' using errcode='42501';end if;
end $function$

CREATE OR REPLACE FUNCTION store_private.own_admin_security_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare own_role text;
begin
 if not store_private.admin_session_active() then raise exception 'Active session required' using errcode='42501';end if;
 select access_role into own_role from public.store_admins where user_id=auth.uid();
 if own_role is not null then return jsonb_build_object('paused',exists(select 1 from store_private.admin_mfa_pauses where user_id=auth.uid()),'pending',false,'access_role',own_role);end if;
 if exists(select 1 from auth.users u join store_private.admin_invitations i on lower(i.email)=lower(u.email) where u.id=auth.uid() and u.email_confirmed_at is not null and i.expires_at>now()) then
 return jsonb_build_object('paused',false,'pending',true,'access_role',null);end if;
 raise exception 'Administrator or current invitation required' using errcode='42501';
end; $function$

CREATE OR REPLACE FUNCTION store_private.own_retention_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE completed timestamptz; active_job boolean; backlog boolean; failed boolean;
BEGIN
 PERFORM store_private.require_workspace_admin();
 SELECT completed_at INTO completed FROM store_private.analytics_retention_state WHERE singleton;
 SELECT active INTO active_job FROM cron.job WHERE jobname='store-analytics-retention';
 SELECT status NOT IN ('succeeded','running','starting') INTO failed FROM cron.job_run_details
  WHERE jobid IN(SELECT jobid FROM cron.job WHERE jobname='store-analytics-retention') ORDER BY runid DESC LIMIT 1;
 backlog:=EXISTS(SELECT 1 FROM store_private.analytics_events WHERE created_at<now()-interval '91 days')
  OR EXISTS(SELECT 1 FROM store_private.analytics_sessions WHERE last_seen<now()-interval '91 days');
 RETURN jsonb_build_object('healthy',coalesce(active_job,false) AND coalesce(completed>now()-interval '26 hours',false) AND NOT backlog AND NOT coalesce(failed,false),'last_completed_at',completed,'retention_days',90);
END; $function$

CREATE OR REPLACE FUNCTION store_private.product_sales_history(p_before bigint DEFAULT NULL::bigint, p_query text DEFAULT ''::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_state text DEFAULT 'active'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare rows jsonb; summary jsonb;
begin
 perform store_private.require_workspace_admin();
 if p_state is null or p_state not in ('active','voided','all') or p_query is null or char_length(p_query)>150 or (p_from is not null and p_to is not null and p_from>p_to) then raise exception 'Проверьте фильтры истории'; end if;
 with filtered as (
  select s.* from store_private.product_sales s where (p_from is null or s.sold_on>=p_from) and (p_to is null or s.sold_on<=p_to)
  and (p_state='all' or (p_state='active' and s.voided_at is null) or (p_state='voided' and s.voided_at is not null))
  and (btrim(p_query)='' or position(lower(btrim(p_query)) in lower(s.product_label))>0 or s.product_id::text=btrim(p_query))
 ), page as (
  select s.* from filtered s where p_before is null or (s.sold_on,s.id)<(select sold_on,id from store_private.product_sales where id=p_before)
  order by s.sold_on desc,s.id desc limit 31
 )
 select (select coalesce(jsonb_agg(jsonb_build_object('id',id::text,'product_id',product_id::text,'product_label',product_label,'variant',variant,'quantity',quantity,'amount',amount,'sold_on',sold_on,'recorded_at',recorded_at,'actor_label',actor_label,'legacy',legacy,'voided_at',voided_at,'voided_label',voided_label,'void_reason',void_reason) order by sold_on desc,id desc),'[]'::jsonb) from page),
 (select jsonb_build_object('count',count(*) filter(where voided_at is null),'quantity',coalesce(sum(quantity) filter(where voided_at is null),0),'amount',coalesce(sum(amount) filter(where voided_at is null),0)) from filtered)
 into rows,summary;
 return jsonb_build_object('rows',rows,'summary',summary);
end $function$

CREATE OR REPLACE FUNCTION store_private.purge_analytics_history()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET lock_timeout TO '2s'
AS $function$
DECLARE n bigint; e bigint:=0; s bigint:=0; l bigint:=0; cutoff timestamptz:=now()-interval '90 days';
BEGIN
 IF NOT pg_try_advisory_xact_lock(840120261013::bigint) THEN RETURN jsonb_build_object('skipped',true);END IF;
 FOR i IN 1..50 LOOP
  DELETE FROM store_private.analytics_events WHERE event_id IN
   (SELECT event_id FROM store_private.analytics_events WHERE created_at<cutoff ORDER BY created_at LIMIT 10000);
  GET DIAGNOSTICS n=ROW_COUNT;e:=e+n;EXIT WHEN n<10000;
 END LOOP;
 FOR i IN 1..50 LOOP
  DELETE FROM store_private.analytics_sessions WHERE session_id IN
   (SELECT session_id FROM store_private.analytics_sessions WHERE last_seen<cutoff ORDER BY last_seen LIMIT 10000);
  GET DIAGNOSTICS n=ROW_COUNT;s:=s+n;EXIT WHEN n<10000;
 END LOOP;
 FOR i IN 1..50 LOOP
  DELETE FROM store_private.analytics_limits WHERE key IN
   (SELECT key FROM store_private.analytics_limits WHERE window_at<now()-interval '1 day' ORDER BY window_at LIMIT 10000);
  GET DIAGNOSTICS n=ROW_COUNT;l:=l+n;EXIT WHEN n<10000;
 END LOOP;
 -- Keep one month of this job's operational history, without touching other jobs.
 DELETE FROM cron.job_run_details WHERE jobid IN(SELECT jobid FROM cron.job WHERE jobname='store-analytics-retention') AND end_time<now()-interval '30 days';
 INSERT INTO store_private.analytics_retention_state VALUES(true,clock_timestamp(),e,s,l)
 ON CONFLICT(singleton) DO UPDATE SET completed_at=excluded.completed_at,events_deleted=excluded.events_deleted,sessions_deleted=excluded.sessions_deleted,limits_deleted=excluded.limits_deleted;
 RETURN jsonb_build_object('events_deleted',e,'sessions_deleted',s,'limits_deleted',l);
END; $function$

CREATE OR REPLACE FUNCTION store_private.record_product_sale(p_operation_id uuid, p_product_id bigint, p_revision bigint, p_sold_on date, p_amount numeric, p_variant text, p_quantity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.products%rowtype; previous store_private.product_sales%rowtype;
 q jsonb; stock integer; remaining integer; archive text; visible boolean; before_data jsonb; after_data jsonb; label text; sale_id bigint;
begin
 perform store_private.require_workspace_admin();
 if p_operation_id is null or p_product_id is null or p_revision is null or p_sold_on is null or p_sold_on<'2000-01-01'::date or p_sold_on>store_private.business_today()
 or p_amount is null or not(p_amount>=0 and p_amount<=999999999 and p_amount=trunc(p_amount))
 or p_variant is null or char_length(p_variant)>100 or p_quantity is null or p_quantity not between 1 and 9999 then
  raise exception 'Проверьте дату, целую сумму в EUR и количество';
 end if;
 p_variant:=store_private.normalize_variant(p_variant);
 select * into p from public.products where id=p_product_id for update;
 select * into previous from store_private.product_sales where operation_id=p_operation_id;
 if found then
  if previous.actor_id<>auth.uid() or previous.product_id<>p_product_id or previous.sold_on<>p_sold_on or previous.amount<>p_amount or store_private.normalize_variant(previous.variant)<>p_variant or previous.quantity<>p_quantity then raise exception 'Эта операция уже записана с другими данными'; end if;
  return jsonb_build_object('sale_id',previous.id::text,'product',case when p.id is null then null else to_jsonb(p) end,'already_recorded',true);
 end if;
 if p.id is null then raise exception 'Товар больше не существует'; end if;
 if p.revision<>p_revision then raise exception 'Карточка изменилась. Обновите список и повторите продажу'; end if;
 if p.archive_status='sold' then raise exception 'Вещь уже продана'; end if;
 before_data:=jsonb_build_object('available',p.available,'archive_status',p.archive_status,'reserved',p.reserved,'stock_quantities',p.stock_quantities);
 q:=store_private.normalize_stock(p.stock_quantities); visible:=p.available; archive:=p.archive_status;
 if p.archive_status='legacy' then
  -- A historical confirmation must not invent or deduct a historical balance.
  visible:=false;archive:='sold';
 else
  if q is null then
   if p_quantity<>1 then raise exception 'Сначала укажите остатки по размерам в карточке'; end if;
   -- Legacy stock semantics are one item per card until explicit quantities exist.
   visible:=false;archive:='sold';
  else
   if not(q ? p_variant) then raise exception 'Размер изменился. Обновите карточку'; end if;
   stock:=(q->>p_variant)::integer;
   if p_quantity>stock then raise exception 'Недостаточно остатка выбранного размера'; end if;
   q:=jsonb_set(q,array[p_variant],to_jsonb(stock-p_quantity));
   select coalesce(sum(value::integer),0) into remaining from jsonb_each_text(q);
   if remaining=0 then visible:=false;archive:='sold'; end if;
  end if;
 end if;
 after_data:=jsonb_build_object('available',visible,'archive_status',archive,'reserved',false,'stock_quantities',q);
 select coalesce(nullif(a.display_name,''),u.email,auth.uid()::text) into label from public.store_admins a join auth.users u on u.id=a.user_id where a.user_id=auth.uid();
 insert into store_private.product_sales(operation_id,product_id,product_label,variant,quantity,amount,sold_on,actor_id,actor_label,legacy,before_state,after_state)
 values(p_operation_id,p.id,concat_ws(' ',p.brand,p.name),p_variant,p_quantity,p_amount,p_sold_on,auth.uid(),label,p.archive_status is not distinct from 'legacy',before_data,after_data) returning id into sale_id;
 update public.products set available=visible,archive_status=archive,reserved=false,stock_quantities=q where id=p.id returning * into p;
 return jsonb_build_object('sale_id',sale_id::text,'product',to_jsonb(p));
end $function$

CREATE OR REPLACE FUNCTION store_private.remove_workspace_admin(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform store_private.require_workspace_admin(true);
 if p_user_id=auth.uid() or exists(select 1 from public.store_admins where user_id=p_user_id and access_role='owner') then raise exception 'Доступ владельца нельзя отключить здесь'; end if;
 delete from public.store_admins where user_id=p_user_id and access_role='admin';
 -- Membership checks deny the revoked user even with an unexpired access token.
 return store_private.workspace_team();
end $function$

CREATE OR REPLACE FUNCTION store_private.save_commission_terms(p_product bigint, p_revision bigint, p_owner text, p_due numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare existing bigint;result jsonb;
begin
 perform store_private.require_workspace_admin(true);
 if p_product is null or p_revision is null or p_owner is null or char_length(p_owner)>100 then raise exception 'Проверьте владельца и артикул';end if;
 perform 1 from public.products where id=p_product and on_commission and available for update;
 if not found then raise exception 'Вещь больше не находится на комиссии в каталоге';end if;
 select revision into existing from store_private.commission_terms where product_id=p_product for update;
 if p_revision<>coalesce(existing,0) then raise exception 'Условия уже изменены. Обновите список.' using errcode='40001';end if;
 insert into store_private.commission_terms(product_id,owner_ref,due_per_unit,updated_by) values(p_product,btrim(p_owner),p_due,auth.uid())
 on conflict(product_id) do update set owner_ref=excluded.owner_ref,due_per_unit=excluded.due_per_unit,revision=store_private.commission_terms.revision+1,updated_at=now(),updated_by=auth.uid()
 returning to_jsonb(commission_terms) into result;return result;
end $function$

CREATE OR REPLACE FUNCTION store_private.save_finance_entry(p_id uuid, p_revision bigint, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e store_private.finance_entries%rowtype; previous store_private.finance_entries%rowtype; existing boolean; target_sale bigint; today date:=(now() at time zone store_private.business_time_zone())::date;
begin
 perform store_private.require_workspace_admin(true);
 if p_id is null or p_revision is null or p_values is null or jsonb_typeof(p_values)<>'object' then raise exception 'Некорректная запись'; end if;
 if exists(select 1 from jsonb_object_keys(p_values) k where k not in ('product_id','product_label','status','on_commission','opened_on','completed_on','quantity','amount','received','purchase_cost','expenses','owner_due','owner_paid','owner_ref','client_ref','note')) then raise exception 'Неизвестное поле финансовой записи'; end if;
 -- Same order as the sale-void transaction: sale ledger, then finance row.
 select sale_id into target_sale from store_private.finance_entries where id=p_id;
 if target_sale is not null then perform 1 from store_private.product_sales where id=target_sale for update; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,160215));
 select * into previous from store_private.finance_entries where id=p_id for update;existing:=found;
 if p_revision<>(case when existing then previous.revision else 0 end) then raise exception 'Запись уже изменена. Обновите отчёт и откройте её заново.' using errcode='40001'; end if;
 if previous.merged_into is not null then raise exception 'Заказ связан с продажей. Редактируйте объединённую запись.'; end if;
 if existing then e:=previous;
 else e.id:=p_id;e.kind:='order';e.status:='active';e.on_order:=true;e.on_commission:=false;e.quantity:=1;e.owner_ref:='';e.client_ref:='';e.note:=''; end if;
 if e.sale_id is not null and p_values ?| array['product_id','product_label','status','on_commission','opened_on','completed_on','quantity','amount'] then
  raise exception 'Дату, сумму и статус продажи изменяют через историю продаж';
 end if;
 e:=jsonb_populate_record(e,p_values);
 if e.product_label is null or e.amount is null or e.quantity is null or e.on_commission is null or e.opened_on is null
  or e.opened_on<date '2000-01-01' or e.opened_on>today or e.completed_on>today
  or e.status is null or e.status not in ('active','completed','cancelled')
  or (e.status='active' and e.completed_on is not null) then raise exception 'Проверьте название, сумму, количество, дату и статус'; end if;
 if e.product_id is not null and (not existing or e.product_id is distinct from previous.product_id)
  and not exists(select 1 from public.products where id=e.product_id) then raise exception 'Товар с таким артикулом не найден'; end if;
 if existing then
  update store_private.finance_entries set product_id=e.product_id,product_label=btrim(e.product_label),status=e.status,on_commission=e.on_commission,
   opened_on=e.opened_on,completed_on=e.completed_on,quantity=e.quantity,amount=e.amount,received=e.received,purchase_cost=e.purchase_cost,expenses=e.expenses,
   owner_due=e.owner_due,owner_paid=e.owner_paid,owner_ref=btrim(e.owner_ref),client_ref=btrim(e.client_ref),note=btrim(e.note),
   revision=revision+1,updated_at=now(),updated_by=auth.uid() where id=p_id returning * into e;
 else
  insert into store_private.finance_entries(id,product_id,product_label,kind,status,on_commission,on_order,opened_on,completed_on,quantity,amount,received,purchase_cost,expenses,owner_due,owner_paid,owner_ref,client_ref,note,updated_by)
  values(p_id,e.product_id,btrim(e.product_label),'order',e.status,e.on_commission,true,e.opened_on,e.completed_on,e.quantity,e.amount,e.received,e.purchase_cost,e.expenses,e.owner_due,e.owner_paid,btrim(e.owner_ref),btrim(e.client_ref),btrim(e.note),auth.uid()) returning * into e;
 end if;
 return to_jsonb(e);
end $function$

CREATE OR REPLACE FUNCTION store_private.save_product_costs(p_product bigint, p_revision bigint, p_purchase numeric, p_expenses numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_cost store_private.product_costs%rowtype; saved store_private.product_costs%rowtype;
begin
 perform store_private.require_workspace_admin(true);
 -- Same first lock as recording a sale: snapshot and cost edits cannot interleave.
 perform 1 from public.products where id=p_product for update;
 if not found then raise exception 'Карточка не найдена'; end if;
 select * into old_cost from store_private.product_costs where product_id=p_product for update;
 if p_revision is null or p_revision<>coalesce(old_cost.revision,0) then
  -- An identical retry after a lost response is safe and does not add audit noise.
  if old_cost.revision=p_revision+1 and old_cost.purchase_per_unit is not distinct from p_purchase and old_cost.expenses_per_unit is not distinct from p_expenses then return to_jsonb(old_cost); end if;
  raise exception 'Закупка уже изменена. Откройте карточку заново и сравните суммы.' using errcode='40001';
 end if;
 if old_cost.product_id is not null and old_cost.purchase_per_unit is not distinct from p_purchase and old_cost.expenses_per_unit is not distinct from p_expenses then return to_jsonb(old_cost); end if;
 insert into store_private.product_costs(product_id,purchase_per_unit,expenses_per_unit,updated_by)
 values(p_product,p_purchase,p_expenses,auth.uid()) on conflict(product_id) do update set purchase_per_unit=excluded.purchase_per_unit,
  expenses_per_unit=excluded.expenses_per_unit,revision=product_costs.revision+1,updated_at=now(),updated_by=auth.uid() returning * into saved;
 return to_jsonb(saved);
end $function$

CREATE OR REPLACE FUNCTION store_private.save_upload_day(p_day date, p_manager_id uuid, p_note text, p_revision bigint, p_reset boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare before_row jsonb; after_row jsonb; label text; existing bigint;
begin
 perform store_private.require_workspace_admin(true);
 if p_day is null or p_day<(now() at time zone store_private.business_time_zone())::date or p_day>(now() at time zone store_private.business_time_zone())::date+366 then raise exception 'Можно менять сегодняшнее и будущее дежурство в течение года'; end if;
 if p_note is null or char_length(p_note)>300 or p_reset is null then raise exception 'Примечание: до 300 символов'; end if;
 if p_manager_id is not null then
  select coalesce(nullif(display_name,''),'Менеджер') into label from public.store_admins where user_id=p_manager_id;
  if not found then raise exception 'У менеджера нет доступа к админке'; end if;
 end if;
 perform pg_advisory_xact_lock(172605,p_day-date '2000-01-01');
 select revision,to_jsonb(d) into existing,before_row from store_private.upload_day_overrides d where day=p_day for update;
 if p_revision is distinct from coalesce(existing,0) then raise exception 'Дежурство уже изменено. Обновите расписание и повторите.' using errcode='40001'; end if;
 if p_reset then delete from store_private.upload_day_overrides where day=p_day;
 else
  insert into store_private.upload_day_overrides(day,manager_id,manager_label,note,updated_by)
  values(p_day,p_manager_id,coalesce(label,''),btrim(p_note),auth.uid()) on conflict(day) do update set manager_id=excluded.manager_id,manager_label=excluded.manager_label,note=excluded.note,revision=store_private.upload_day_overrides.revision+1,updated_at=now(),updated_by=auth.uid()
  returning to_jsonb(upload_day_overrides) into after_row;
 end if;
 insert into store_private.upload_schedule_changes(actor_id,kind,day,before_data,after_data) values(auth.uid(),case when p_reset then 'reset_day' else 'day' end,p_day,before_row,after_row);
 return jsonb_build_object('saved',true);
end $function$

CREATE OR REPLACE FUNCTION store_private.save_upload_rotation(p_starts_on date, p_manager_ids uuid[], p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare before_row jsonb; after_row jsonb; labels jsonb; existing bigint;
begin
 perform store_private.require_workspace_admin(true);
 if p_starts_on is null or p_starts_on<(now() at time zone store_private.business_time_zone())::date or p_starts_on>(now() at time zone store_private.business_time_zone())::date+366 then raise exception 'Новая очередь может начинаться сегодня или в течение следующего года'; end if;
 if p_manager_ids is null or cardinality(p_manager_ids) not between 1 and 100 or array_ndims(p_manager_ids)<>1
  or array_position(p_manager_ids,null) is not null
  or cardinality(p_manager_ids)<>(select count(distinct id) from unnest(p_manager_ids) id) then raise exception 'Выберите менеджеров без повторений'; end if;
 if exists(select 1 from unnest(p_manager_ids) id where not exists(select 1 from public.store_admins a where a.user_id=id)) then raise exception 'Участник очереди должен иметь доступ к админке'; end if;
 -- Serialize same-day edits, including a first insert into an empty date.
 perform pg_advisory_xact_lock(172604,p_starts_on-date '2000-01-01');
 select revision,to_jsonb(r) into existing,before_row from store_private.upload_rotations r where starts_on=p_starts_on for update;
 if p_revision is distinct from coalesce(existing,0) then raise exception 'Очередь уже изменена. Обновите расписание и повторите.' using errcode='40001'; end if;
 select jsonb_object_agg(user_id::text,coalesce(nullif(display_name,''),'Менеджер')) into labels from public.store_admins where user_id=any(p_manager_ids);
 insert into store_private.upload_rotations(starts_on,manager_ids,manager_labels,updated_by)
 values(p_starts_on,p_manager_ids,labels,auth.uid()) on conflict(starts_on) do update set manager_ids=excluded.manager_ids,manager_labels=excluded.manager_labels,revision=store_private.upload_rotations.revision+1,updated_at=now(),updated_by=auth.uid()
 returning to_jsonb(upload_rotations) into after_row;
 insert into store_private.upload_schedule_changes(actor_id,kind,day,before_data,after_data) values(auth.uid(),'rotation',p_starts_on,before_row,after_row);
 return jsonb_build_object('saved',true);
end $function$

CREATE OR REPLACE FUNCTION store_private.save_workspace_profile(p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform store_private.require_workspace_admin();
 if p_name is null or char_length(btrim(p_name)) not between 1 and 100 then raise exception 'Имя должно содержать от 1 до 100 символов'; end if;
 update public.store_admins set display_name=btrim(p_name) where user_id=auth.uid();
 return store_private.workspace_team();
end $function$

CREATE OR REPLACE FUNCTION store_private.touch_own_admin_session()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '2s'
AS $function$
DECLARE s auth.sessions%ROWTYPE; t timestamptz; deadline timestamptz;
BEGIN
 -- Lock the actual caller's session; do not accept a client-selected session ID or time.
 SELECT ss.* INTO s FROM auth.sessions ss JOIN auth.users u ON u.id=ss.user_id
 WHERE ss.id::text=auth.jwt()->>'session_id' AND ss.user_id=auth.uid()
 AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<=now())
 FOR UPDATE OF ss;
 t:=clock_timestamp();
 IF s.id IS NULL OR s.created_at IS NULL THEN RAISE EXCEPTION 'Active session required' USING ERRCODE='42501';END IF;
 deadline:=least(s.created_at+interval '30 days',s.not_after);
 IF deadline<=t THEN
  RAISE EXCEPTION 'Session expired; sign in again' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.store_admins WHERE user_id=s.user_id)
 AND NOT EXISTS(SELECT 1 FROM auth.users u JOIN store_private.admin_invitations i ON lower(i.email)=lower(u.email)
  WHERE u.id=s.user_id AND u.email_confirmed_at IS NOT NULL AND i.expires_at>t) THEN
  RAISE EXCEPTION 'Administrator or current invitation required' USING ERRCODE='42501';
 END IF;
 INSERT INTO store_private.admin_session_activity(session_id,last_seen) VALUES(s.id,t)
 ON CONFLICT(session_id) DO UPDATE SET last_seen=greatest(admin_session_activity.last_seen,excluded.last_seen);
 RETURN jsonb_build_object('server_now',t,'expires_at',deadline,'idle_expires_at',deadline);
END; $function$

CREATE OR REPLACE FUNCTION store_private.valid_product_photos(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare photo jsonb;
begin
 if jsonb_typeof(value)<>'array' or jsonb_array_length(value)>20 then return false;end if;
 for photo in select * from jsonb_array_elements(value) loop
  if jsonb_typeof(photo)<>'string' or length(photo #>> '{}')>2048 or not coalesce(store_private.valid_product_image(photo #>> '{}'),false) then return false;end if;
 end loop;
 return true;
end;$function$

CREATE OR REPLACE FUNCTION store_private.void_product_sale(p_sale_id bigint, p_revision bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s store_private.product_sales%rowtype; p public.products%rowtype; label text; target bigint;
begin
 perform store_private.require_workspace_admin(true);
 if p_reason is null or char_length(btrim(p_reason)) not between 3 and 1000 then raise exception 'Укажите причину отмены (от 3 до 1000 символов)'; end if;
 select product_id into target from store_private.product_sales where id=p_sale_id;
 -- Same lock order as recording: product first, then ledger.
 select * into p from public.products where id=target for update;
 select * into s from store_private.product_sales where id=p_sale_id for update;
 if not found then raise exception 'Продажа не найдена'; end if;
 if s.voided_at is not null then return jsonb_build_object('product',case when p.id is null then null else to_jsonb(p) end,'already_voided',true); end if;
 if p.id is not null then
  if p_revision is null or p_revision<>p.revision then raise exception 'Карточка изменилась. Обновите список и повторите'; end if;
  if exists(select 1 from store_private.product_sales where product_id=p.id and id>s.id and voided_at is null)
  or jsonb_build_object('available',p.available,'archive_status',p.archive_status,'reserved',p.reserved,'stock_quantities',p.stock_quantities) is distinct from s.after_state then
   raise exception 'После продажи остатки или статус изменились. Сначала отмените более поздние продажи и проверьте карточку';
  end if;
 end if;
 select coalesce(nullif(a.display_name,''),u.email,auth.uid()::text) into label from public.store_admins a join auth.users u on u.id=a.user_id where a.user_id=auth.uid();
 update store_private.product_sales set voided_at=now(),voided_by=auth.uid(),voided_label=label,void_reason=btrim(p_reason) where id=s.id;
 if p.id is not null then
  update public.products set available=(s.before_state->>'available')::boolean,archive_status=s.before_state->>'archive_status',reserved=false,stock_quantities=nullif(s.before_state->'stock_quantities','null'::jsonb) where id=p.id returning * into p;
 end if;
 return jsonb_build_object('product',case when p.id is null then null else to_jsonb(p) end);
end $function$

CREATE OR REPLACE FUNCTION store_private.workspace_team()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; pending jsonb:='[]'::jsonb;
begin
 perform store_private.require_workspace_admin();
 select jsonb_build_object('current_user_id',auth.uid(),'members',coalesce(jsonb_agg(jsonb_build_object('user_id',a.user_id,'display_name',a.display_name,'email',u.email,'access_role',a.access_role) order by a.access_role desc,a.display_name,u.email),'[]'::jsonb)) into result from public.store_admins a join auth.users u on u.id=a.user_id;
 if store_private.admin_mfa_fresh() and exists(select 1 from public.store_admins where user_id=auth.uid() and access_role='owner') then
  select coalesce(jsonb_agg(jsonb_build_object(
   'email',i.email,'display_name',i.display_name,'delivery_status',case when i.delivery_status='pending' and i.created_at<now()-interval '2 minutes' then 'unknown' else i.delivery_status end,'delivery_error',i.delivery_error,
   'email_confirmed',u.email_confirmed_at is not null,
   'mfa_confirmed',exists(select 1 from auth.mfa_factors f where f.user_id=u.id and f.status='verified' and f.factor_type='totp'),
   'ready',i.delivery_status in ('sent','unknown') and u.email_confirmed_at is not null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()) and exists(select 1 from auth.mfa_factors f where f.user_id=u.id and f.status='verified' and f.factor_type='totp')
  ) order by i.created_at),'[]'::jsonb)
  into pending from store_private.admin_invitations i left join auth.users u on lower(u.email)=lower(i.email)
  where i.expires_at>now() and not exists(select 1 from public.store_admins a where a.user_id=u.id);
 end if;
 return result||jsonb_build_object('pending_invitations',pending);
end; $function$
